First, create a context to manage the tooltip state:

```jsx
import React, { createContext, useState } from 'react';

export const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const openTooltip = (content, position) => {
    setTooltip({ content, position });
  };

  return (
    <TooltipContext.Provider value={{ openTooltip, closeTooltip, tooltip }}>
      {children}
    </TooltipContext.Provider>
  );
};
```

Then, create the Tooltip component:

```jsx
import React, { useContext } from 'react';
import { TooltipContext } from './TooltipContext';

const Tooltip = ({ children }) => {
  const { tooltip, closeTooltip } = useContext(TooltipContext);

  if (!tooltip) return children;

  const { content, position } = tooltip;

  return (
    <div
      className="tooltip"
      style={{ top: position.y, left: position.x }}
      onMouseLeave={closeTooltip}
    >
      {content}
    </div>
  );
};

export default Tooltip;
```

Now, you can use the Tooltip component in your components:

```jsx
import React, { useRef } from 'react';
import Tooltip from './Tooltip';
import TooltipProvider from './TooltipContext';

const MyComponent = () => {
  const tooltipRef = useRef(null);

  const handleMouseOver = (e) => {
    if (tooltipRef.current) {
      TooltipProvider.openTooltip('This is the tooltip content', {
        x: e.clientX,
        y: e.clientY,
      });
    }
  };

  return (
    <div ref={tooltipRef} onMouseOver={handleMouseOver}>
      Hover me!
      <Tooltip />
    </div>
  );
};

export default MyComponent;
```

Finally, wrap your application with the TooltipProvider:

```jsx
import React from 'react';
import TooltipProvider from './TooltipContext';

function MyApp({ Component, pageProps }) {
  return (
    <TooltipProvider>
      <Component {...pageProps} />
    </TooltipProvider>
  );
}

export default MyApp;
```

Now, when you hover over the element with the `onMouseOver` event, the tooltip will open, and when you move the mouse out of the tooltip, it will close. If another tooltip is opened, the previously opened tooltip will close.

