To create a CSV downloader using web workers in Ember Octane, follow these steps:

1. Install the necessary dependencies:

```bash
ember install ember-cli-htmlbars
ember install ember-cli-typescript
ember install ember-cli-web-worker
```

2. Create a new service for handling the CSV download:

```bash
touch app/services/csv-downloader.ts
```

3. Implement the CSV downloader service:

```typescript
// app/services/csv-downloader.ts
import { inject as service } from '@ember/service';
import { task, timeout } from 'ember-concurrency';
import { A } from '@ember/array';
import { computed } from '@ember/object';
import { read } from 'ember-cli-htmlbars';
import { worker } from 'ember-cli-web-worker';

export default class CsvDownloaderService {
  @service('store') store;

  @task
  async downloadCSV(data) {
    const headers = data[0];
    const rows = data.slice(1);

    const worker = worker(async () => {
      const blob = new Blob([this.csvData(headers, rows)], {
        type: 'text/csv;charset=utf-8;',
      });

      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = 'export.csv';
      link.click();
      URL.revokeObjectURL(url);
    });

    await worker.perform(data);
  }

  csvData(headers, rows) {
    const csvRows = rows.map((row) => {
      return A(headers)
        .map((header) => {
          const value = row[header];
          return value === null ? '' : value.toString();
        })
        .join(',');
    });

    return [
      csvRows[0],
      ...csvRows.slice(1),
    ].join('\n');
  }

  @computed('store.content')
  get data() {
    const content = this.store.content;
    return content ? content.mapBy('csvData') : [];
  }

  @computed('data')
  get isLoading() {
    return this.data.length > 0 && this.downloadCSV.isRunning;
  }
}
```

